<script setup lang="ts">
import { reactive, watch } from 'vue';
import { ScanEye, RefreshCw } from '@lucide/vue';
import { api } from '../services/api';
import { notify, useFeedback } from '../services/feedback';
import { ref } from 'vue';
import type { Hazard } from '../types';
const props = defineProps<{ report: Hazard }>();
const emit = defineEmits<{ refresh: [] }>();
type Draft = { verdict: string; note: string; confirmed: boolean; version: number; busy: boolean };
const drafts = reactive<Record<string, Draft>>({}); const error = ref('');
useFeedback([error]);
const statuses: Record<string, string> = { not_assessed: 'Not assessed — no automated result', queued: 'Local check pending', unavailable: 'Local detector unavailable', possible_ai: 'Possible AI-generated image', low_signal: 'Low AI signal — authenticity still needs review', inconclusive: 'Automated result inconclusive' };
watch(() => props.report.photos, photos => { for (const photo of photos) { if (!photo.authenticity) continue; const old = drafts[photo.id]; drafts[photo.id] = { verdict: old?.verdict || photo.authenticity.review?.verdict || '', note: old?.note || photo.authenticity.review?.note || '', confirmed: old?.version === photo.authenticity.version ? old.confirmed : false, version: photo.authenticity.version, busy: false }; } }, { immediate: true });
function label(photo: Hazard['photos'][number]) { const kind = photo.photo_type || 'incident'; return `${kind === 'incident' ? 'Incident' : 'Resolution'} photo ${props.report.photos.filter(item => (item.photo_type || 'incident') === kind).findIndex(item => item.id === photo.id) + 1}`; }
async function save(photo: Hazard['photos'][number]) {
  const draft = drafts[photo.id]; if (!draft || draft.busy) return; draft.busy = true; error.value = '';
  try { await api(`/api/admin/reports/${props.report.id}/photos/${photo.id}/review`, { method: 'POST', body: JSON.stringify({ assessment_version: draft.version, verdict: draft.verdict, review_note: draft.note, confirmed_reviewed: draft.confirmed }) }); draft.confirmed = false; notify('Image review recorded. Factual verification remains a separate action.'); emit('refresh'); }
  catch (e) { error.value = (e as Error).message; } finally { draft.busy = false; }
}
</script>
<template><section v-if="report.photos.some(photo => photo.authenticity)" class="image-review-panel review-step"><h3><ScanEye :size="24" aria-hidden="true" />Private image authenticity review</h3><p>AI scores are advisory. A low score does not prove a genuine photo, and a high score does not prove the incident is false. Inspect the images above and corroborate the incident independently.</p><button type="button" class="button secondary" @click="emit('refresh')"><RefreshCw :size="18" aria-hidden="true" />Refresh image assessments</button><template v-for="photo in report.photos" :key="photo.id"><form v-if="photo.authenticity && drafts[photo.id]" :aria-label="`${label(photo)} review`" class="form-body image-review-form" @submit.prevent="save(photo)"><h4>{{ label(photo) }}</h4><p role="status">{{ statuses[photo.authenticity.status] || 'Not assessed' }}</p><p v-if="photo.authenticity.probability != null" class="field-help">AI likelihood: {{ Math.round(photo.authenticity.probability * 100) }}% · {{ photo.authenticity.model }}. Model estimate, not proof.</p><p v-if="photo.authenticity.status === 'queued'" class="field-help">You may review manually now. Saving your decision stops the pending check for this photo.</p><p v-if="photo.authenticity.review" class="field-help">Last decision: {{ photo.authenticity.review.verdict.replaceAll('_', ' ') }} · {{ new Date(photo.authenticity.review.at).toLocaleString('en-PH', { timeZone: 'Asia/Manila' }) }} PHT.</p><label>Image review decision<select v-model="drafts[photo.id]!.verdict" aria-label="Image review decision" required><option value="" disabled>Choose your assessment</option><option value="accepted_evidence">Accept as supporting evidence after review</option><option value="suspected_ai">Suspected AI or manipulated image</option><option value="inconclusive">Inconclusive — further checks needed</option></select></label><label>Image review notes<textarea v-model="drafts[photo.id]!.note" aria-label="Image review notes" required minlength="15" maxlength="1000" rows="3" placeholder="Record visual checks and independent corroboration. Explain any disagreement with the detector."></textarea></label><label class="checkbox-label"><input v-model="drafts[photo.id]!.confirmed" type="checkbox" required>I inspected this image and reviewed the available assessment.</label><button type="submit" class="button primary" :disabled="drafts[photo.id]!.busy">{{ drafts[photo.id]!.busy ? 'Saving review…' : 'Save image review' }}</button></form></template></section></template>
<style scoped>.image-review-panel { display: grid; gap: 18px; margin-block: 24px; } .image-review-form { border: 1px solid var(--border, #d7e3dc); border-radius: 16px; padding: 20px; } .image-review-panel h3 { display: flex; align-items: center; gap: 10px; } .image-review-panel p { line-height: 1.7; overflow-wrap: anywhere; }</style>
